<div class="admin-title"><div><h1>Đơn hàng</h1><p>Quản lý đơn COD và thanh toán PayOS.</p></div></div><section class="panel"><form class="order-filters"><input name="q" value="{{ request('q') }}" placeholder="Mã đơn, tên hoặc số điện thoại"><select name="status"><option value="">Tất cả trạng thái</option>@foreach($labels as $value=>$label)<option value="{{ $value }}" @selected(request('status')===$value)>{{ $label }}</option>@endforeach</select><button class="btn">Lọc đơn</button></form><div class="table-wrap"><table><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Sản phẩm</th><th>Tổng tiền</th><th>Thanh toán</th><th>Trạng thái</th><th></th></tr></thead><tbody>@forelse($orders as $order)<tr><td><b>{{ $order->code }}</b><small>{{ $order->created_at->format('d/m/Y H:i') }}</small></td><td><b>{{ $order->customer_name }}</b><small>{{ $order->phone }}</small></td><td>{{ $order->items->sum('quantity') }} sản phẩm</td><td><b>{{ number_format($order->total,0,',','.') }}đ</b></td><td><span class="badge {{ $order->payment_status==='paid'?'on':'warn' }}">{{ $order->payment_status==='paid'?'Đã thanh toán':'Chưa thanh toán' }}</span><small>{{ $order->payment_method==='payos'?'PayOS':'COD' }}</small></td><td><span class="badge">{{ $labels[$order->status]??$order->status }}</span></td><td class="actions"><a href="{{ route('admin.orders.show',$order) }}">Chi tiết</a></td></tr>@empty<tr><td colspan="7" class="empty">Chưa có đơn hàng.</td></tr>@endforelse</tbody></table></div>{{ $orders->links() }}</section>@endsection
